package net.civeira.phylax.feature.observe.observedslo.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.ObservedSloBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class ObservedSloBatchController implements ObservedSloBatchApi {

  /**
   * ObservedSlo
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ObservedSloDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ObservedSloDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ObservedSloEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param name
   * @param origin
   * @param origins
   * @return
   */
  @Override
  public Response observedSloApiBatchDelete(final List<String> uids, final String search,
      final String name, final String origin, final List<String> origins) {
    return deleteController.observedSloApiBatchDelete(uids, search, name, origin, origins);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response observedSloApiBatchDeleteQuery(final String batchId) {
    return deleteController.observedSloApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param name
   * @param origin
   * @param origins
   * @return
   */
  @Override
  public Response observedSloApiBatchDisable(final List<String> uids, final String search,
      final String name, final String origin, final List<String> origins) {
    return disableController.observedSloApiBatchDisable(uids, search, name, origin, origins);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response observedSloApiBatchDisableQuery(final String batchId) {
    return disableController.observedSloApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param name
   * @param origin
   * @param origins
   * @return
   */
  @Override
  public Response observedSloApiBatchEnable(final List<String> uids, final String search,
      final String name, final String origin, final List<String> origins) {
    return enableController.observedSloApiBatchEnable(uids, search, name, origin, origins);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response observedSloApiBatchEnableQuery(final String batchId) {
    return enableController.observedSloApiBatchEnableQuery(batchId);
  }
}
